SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "王宗夔", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁三年条所见人物：王宗夔。", "biography": null, "status": "draft", "id": "3ceeb0c1-ec40-54b0-bda8-091d539db25b"}, {"name": "田昉", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁三年条所见人物：田昉。", "biography": null, "status": "draft", "id": "52714cd9-c93e-5b73-9c57-32e0e0e10f51"}, {"name": "刘建锋", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：刘建锋。", "biography": null, "status": "draft", "id": "084d26d2-8aae-5f9d-9127-ca3c97b203b6"}, {"name": "马殷", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁封马殷为楚王”中为受封者。", "biography": null, "status": "draft", "id": "7115610f-10b4-5211-b4a5-d2d089e6db83"}, {"name": "蒋勋", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259乾宁元年条所见人物：蒋勋。", "biography": null, "status": "draft", "id": "05f4879b-c4c4-5c94-9608-e880d6142ce2"}, {"name": "安仁义", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：安仁义。", "biography": null, "status": "draft", "id": "818f8166-7d71-5f56-8c1b-a53a37fca14f"}, {"name": "董昌", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：董昌。", "biography": null, "status": "draft", "id": "873d5b10-b461-5308-baa9-da26022436b4"}, {"name": "钱镠", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“钱氏军队攻取温州，卢佶被杀”中为发令者。", "biography": null, "status": "draft", "id": "d61d1f96-7af5-5367-8be8-7a25ee7c85ae"}, {"name": "顾全武", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：顾全武。", "biography": null, "status": "draft", "id": "82b73ae4-434c-5208-8a2d-89b0830434c2"}, {"name": "许再思", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁三年条所见人物：许再思。", "biography": null, "status": "draft", "id": "d8f0fe35-6617-53d5-911b-2680c6a59c66"}, {"name": "汤臼", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁三年条所见人物：汤臼。", "biography": null, "status": "draft", "id": "828781a9-b07d-5777-b8a0-04b3cf2e713e"}, {"name": "袁邠", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁三年条所见人物：袁邠。", "biography": null, "status": "draft", "id": "1e9b8e5c-29c8-5223-b927-08168dfe8b65"}, {"name": "李克用", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 908, "description": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "biography": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "status": "draft", "id": "04af206e-fa86-581c-86b9-87a78a8d59a5"}, {"name": "李存信", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的李存信，在此段中为李克用养子。", "biography": null, "status": "draft", "id": "31ad8087-ed47-5400-bf8a-47f2edb81920"}, {"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "五代十国", "birth_year": null, "death_year": 912, "description": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "biography": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "罗弘信", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257文德元年条所见人物：罗弘信。", "biography": null, "status": "draft", "id": "da48e163-21a8-54a2-a3a0-cdef2344d96a"}, {"name": "史俨", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257文德元年条所见人物：史俨。", "biography": null, "status": "draft", "id": "665af188-1b5e-544d-8e0e-a314f3e9a16a"}, {"name": "李承嗣", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：李承嗣。", "biography": null, "status": "draft", "id": "183140df-a690-555d-8a83-342b47cf0422"}]'::jsonb)
