INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "王宗夔攻克龙州杀田昉", "start_year": 896, "end_year": 896, "time_original": "896年春正月；确日未载", "dynasty": "唐", "description": "西川将王宗夔攻克龙州，杀刺史田昉。", "phases": [], "location_name": "龙州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8732cf53-306c-55d5-ba62-e9d71cc76d57"}, {"title": "刘建锋遣马殷讨蒋勋，攻破定胜寨", "start_year": 896, "end_year": 896, "time_original": "896年正月丁已；底本日字如此", "dynasty": "唐", "description": "刘建锋派都指挥使马殷率兵讨蒋勋，攻破定胜寨。", "phases": [], "location_name": "定胜寨", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d4638de4-2dc7-5722-b72e-b7be002dab13"}, {"title": "安仁义舟师至湖州欲渡江援董昌", "start_year": 896, "end_year": 896, "time_original": "896年正月辛未", "dynasty": "唐", "description": "安仁义率舟师到湖州，想渡江援董昌。", "phases": [], "location_name": "湖州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "a74d665b-f025-583f-b2d3-5d2b87fef473"}, {"title": "钱镠遣顾全武许再思守西陵阻渡", "start_year": 896, "end_year": 896, "time_original": "896年正月辛未条", "dynasty": "唐", "description": "钱镠派武勇都指挥使顾全武、都知兵马使许再思守西陵，安仁义不能渡江。", "phases": [], "location_name": "西陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f1d87f19-778e-5d2d-adff-ed1d39483d2d"}, {"title": "董昌遣汤臼守石城袁邠守馀姚", "start_year": 896, "end_year": 896, "time_original": "896年正月条；确日未另载", "dynasty": "唐", "description": "董昌派将汤臼守石城、袁邠守馀姚。", "phases": [], "location_name": "石城、馀姚", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "62c00f9e-8492-5be8-a721-18ef5059cd95"}, {"title": "李克用遣李存信万骑借魏援兖郓，军莘县", "start_year": 896, "end_year": 896, "time_original": "896年闰月；确日未载", "dynasty": "唐", "description": "李克用派蕃汉都指挥使李存信领万骑借道魏救兖郓，驻军莘县。", "phases": [], "location_name": "魏、莘县", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7bb6f5fb-f09a-5809-9f6a-734d5b740176"}, {"title": "朱温遣人警告罗弘信李克用欲吞河朔", "start_year": 896, "end_year": 896, "time_original": "896年闰月莘县驻军后条；确日未载", "dynasty": "唐", "description": "朱温派人告诉罗弘信，李克用有吞河朔之志，返军时魏道将可忧。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "597b5da7-f4ab-561d-9a63-b0afdc9c1f6c"}, {"title": "李存信军纪律不严，侵暴魏民", "start_year": 896, "end_year": 896, "time_original": "896年闰月条；确日未载", "dynasty": "唐", "description": "李存信约束军众不严，部兵侵扰魏民。", "phases": [], "location_name": "魏", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b00fa94e-a7c2-5846-add1-ccb69f6c8901"}, {"title": "罗弘信三万兵夜袭，李存信败保洺州", "start_year": 896, "end_year": 896, "time_original": "896年闰月条；夜袭确日未载", "dynasty": "唐", "description": "罗弘信怒，发三万兵夜袭李存信军。李军溃退保洺州，损失士卒十分之二三，并弃大量军需兵械。", "phases": [], "location_name": "莘县、洺州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d30fff0d-a3f3-51a0-8622-85f4df8846bd"}, {"title": "史俨李承嗣军被隔不能返回", "start_year": 896, "end_year": 896, "time_original": "896年闰月魏袭以后；确日未载", "dynasty": "唐", "description": "史俨、李承嗣军被隔断，无法返回。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "c0ff8e08-b548-5e88-b1fa-698a5a4780a6"}, {"title": "罗弘信与河东断交，转向汴", "start_year": 896, "end_year": 896, "time_original": "896年闰月夜袭以后；关系持续起讫未另载", "dynasty": "唐", "description": "罗弘信自此与河东断绝关系，专心依向汴。", "phases": [], "location_name": "魏、河东、汴", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "cbf7cc39-0794-5c7d-ab04-9e3be428ca2b"}, {"title": "朱温北向拜受罗弘信赠遗，以六兄相称", "start_year": null, "end_year": null, "time_original": "896年闰月条背景；每有赠遗起讫未载", "dynasty": "唐", "description": "朱温图兖郓又担心罗弘信在后，每遇罗赠遗，对使者向北拜受，称罗为年长一倍的六兄。罗相信他的礼遇，朱温得专意东方。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "643c52eb-883d-564b-a2ac-8a33aa93dd3f"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

